#ifdef NDEBUG
#error "Assertions must remain enabled."
#endif
#include <cassert>
#include <iostream>
struct Settings { int textScale; bool shake; };
class Preview {
    Settings saved_{100,true};
    Settings draft_{100,true};
public:
    bool setScale(int value) {
        if(value<100 || value>150) return false;
        draft_.textScale=value;return true;
    }
    void setShake(bool value){draft_.shake=value;}
    void cancel(){draft_=saved_;}
    void commit(){saved_=draft_;}
    Settings shown() const{return draft_;}
    Settings saved() const{return saved_;}
};
int main(){
    Preview p;assert(p.setScale(150));p.setShake(false);
    assert(p.shown().textScale==150 && !p.shown().shake);
    assert(p.saved().textScale==100 && p.saved().shake);
    assert(!p.setScale(151) && !p.setScale(99));
    assert(p.shown().textScale==150);
    p.cancel();assert(p.shown().textScale==100 && p.shown().shake);
    assert(p.setScale(125));p.setShake(false);p.commit();
    assert(p.saved().textScale==125 && !p.saved().shake);
    assert(p.setScale(100));p.cancel();
    assert(p.shown().textScale==125 && !p.shown().shake);
    std::cout<<"settings preview tests passed\n";
}
